let soma = 0;
// escreva aqui o laço que lê os n números
console.log(`Soma: ${soma}`);

lessons.solution:
const n = Number(prompt());
if (n === 0) {
  console.log("Nenhum número");
} else {
  let soma = 0;
  let maior = -Infinity;
  let menor = Infinity;
  for (let i = 0; i < n; i++) {
    const x = Number(prompt());
    soma += x;
    if (x > maior) maior = x;
    if (x < menor) menor = x;
  }
  console.log(`Soma: ${soma}`);
  console.log(`Maior: ${maior}`);
  console.log(`Menor: ${menor}`);
}

