lessons.solution:
class ContaBancaria {
  #saldo = 0;
  constructor(titular) {
    this.titular = titular;
  }
  depositar(valor) {
    this.#saldo += valor;
  }
  sacar(valor) {
    if (valor > this.#saldo) return false;
    this.#saldo -= valor;
    return true;
  }
  get saldo() {
    return this.#saldo;
  }
}

const conta = new ContaBancaria(prompt());
const n = Number(prompt());
for (let i = 0; i < n; i++) {
  const [tipo, texto] = prompt().split(" ");
  const valor = Number(texto);
  if (tipo === "D") {
    conta.depositar(valor);
    console.log(`Depósito de ${valor.toFixed(2)}`);
  } else if (conta.sacar(valor)) {
    console.log(`Saque de ${valor.toFixed(2)}`);
  } else {
    console.log(`Saldo insuficiente para sacar ${valor.toFixed(2)}`);
  }
}
console.log(`Saldo de ${conta.titular}: ${conta.saldo.toFixed(2)}`);

