lessons.solution:
function mergeSort(v) {
  if (v.length <= 1) return v;
  const meio = Math.floor(v.length / 2);
  const a = mergeSort(v.slice(0, meio));
  const b = mergeSort(v.slice(meio));
  const r = [];
  let i = 0;
  let j = 0;
  while (i < a.length && j < b.length) r.push(a[i] <= b[j] ? a[i++] : b[j++]);
  while (i < a.length) r.push(a[i++]);
  while (j < b.length) r.push(b[j++]);
  return r;
}

function buscaBinaria(v, alvo) {
  let ini = 0;
  let fim = v.length;
  while (ini < fim) {
    const meio = Math.floor((ini + fim) / 2);
    if (v[meio] < alvo) ini = meio + 1;
    else fim = meio;
  }
  return ini < v.length && v[ini] === alvo ? ini : -1;
}

const n = Number(prompt());
const numeros = [];
for (let i = 0; i < n; i++) numeros.push(Number(prompt()));
const alvo = Number(prompt());
const ordenado = mergeSort(numeros);
console.log(`Ordenado: ${ordenado.join(" ")}`);
const pos = buscaBinaria(ordenado, alvo);
console.log(pos >= 0 ? `Posição: ${pos}` : "Não encontrado");
